function parseRows(rows, difficulty, start) {
  return rows.trim().split('\n').map((row, index) => {
    const [title, category, problem, requirements, startingState, expectedResult, constraints, example, hint, approach, testing, mistakes, solution] = row.split('|')
    return {id: start + index, difficulty, title, category, problem, requirements, startingState, expectedResult, constraints, example, hint, approach, testing, mistakes, solution}
  })
}

export const reactNativeExercises = [
  ...parseRows(beginnerRows, 'Beginner', 1),
  ...parseRows(intermediateRows, 'Intermediate', 101),
  ...parseRows(advancedRows, 'Advanced', 201),
]
